window.RP_SESSION={"id":"S-18bdff212e36","messages":[{"id":"RP-II-0024378","time":"2026-01-21T19:47:00+09:00","room":"RP II","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":".\n.\n.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0024379","time":"2026-01-21T19:52:00+09:00","room":"RP II","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"하아-...\"\n\n그녀라고는 믿기 힘든 그녀가 시끌벅적한 야시장 한켠에서 맥주를 들이킵니다.\n지금쯤이면 길드의 공터에 모닥불이 타올라 따듯했을터인데...\n...\n\n\"어설픈 용맹을 위해.. 건배~.....\"\n\n여행길 도중 주운 하얀 고양이 한마리의 발에 건배를 해댑니다.\n곧, 안주용 닭꼬치를 집어들어 뜯습니다. 촉촉한 육즙이 입안에 가득 차 흐르고 달콤한 소스가 숯불에 그을려 만들어내는 그 불맛은 황홀하기 그지없습니다.\n\n\"...나중에 데려와야겠다.\"","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0024380","time":"2026-01-21T19:52:00+09:00","room":"RP II","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0024381","time":"2026-01-21T19:52:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
